#define main pin_device_original_main
#include "/mnt/data/nrii_si_pin_device.c"
#undef main

static int pc_contact(const Device*d,int ii,double mask){int i=ii+1;double x=d->x[i];return x<mask||x>d->L-mask;}
static void edge_coeff_tc(const Device*d,int k,int il,int ir,const double*UC,const double*NC,const double*PC,double*jnk,double*jpk){int m=d->m;double z[MAXP+1]={0},mz[MAXP+1]={0},Bn[MAXP+1]={0},Bm[MAXP+1]={0},nl[MAXP+1]={0},nr[MAXP+1]={0},pl[MAXP+1]={0},pr[MAXP+1]={0};for(int q=0;q<=k;q++){double ul=(il==0?(q==0?d->uL:0):UC[(size_t)q*m+il-1]),ur=(ir==d->nn-1?(q==0?d->uR:0):UC[(size_t)q*m+ir-1]);z[q]=ur-ul;mz[q]=-z[q];nl[q]=(il==0?(q==0?d->NL:0):NC[(size_t)q*m+il-1]);nr[q]=(ir==d->nn-1?(q==0?d->NR:0):NC[(size_t)q*m+ir-1]);pl[q]=(il==0?(q==0?d->PL:0):PC[(size_t)q*m+il-1]);pr[q]=(ir==d->nn-1?(q==0?d->PR:0):PC[(size_t)q*m+ir-1]);}s_B_general(z,Bn,k);s_B_general(mz,Bm,k);long double en=0,ep=0;for(int q=0;q<=k;q++){en+=(long double)nr[q]*Bn[k-q]-(long double)nl[q]*Bm[k-q];ep+=(long double)pl[q]*Bn[k-q]-(long double)pr[q]*Bm[k-q];}*jnk=d->rn*(double)en;*jpk=d->rp*(double)ep;}

static void build_A(const Device*d,double mask,double theta_contact,const double*u0,const double*N0,const double*P0,double*Ln,double*Dn,double*Un,double*Lp,double*Dp,double*Up){int m=d->m;for(int ii=0;ii<m;ii++){int i=ii+1;double ui=u0[ii],um=getU(d,u0,i-1),ur=getU(d,u0,i+1),zL=ui-um,zR=ur-ui;double Ni=N0[ii],Pi=P0[ii];Ln[ii]=(ii>0?d->rn*Bfun(-zL):0);Dn[ii]=-d->rn*(Bfun(-zR)+Bfun(zL))-srh_dN(d,Ni,Pi);Un[ii]=(ii<m-1?d->rn*Bfun(zR):0);Lp[ii]=(ii>0?d->rp*Bfun(zL):0);Dp[ii]=-d->rp*(Bfun(zR)+Bfun(-zL))-srh_dP(d,Ni,Pi);Up[ii]=(ii<m-1?d->rp*Bfun(-zR):0);if(pc_contact(d,ii,mask)){double sigma=d->q*d->Nref*(d->mun*N0[ii]+d->mup*P0[ii]);if(sigma>0){double rate=-theta_contact*d->tau0/(d->eps_si/sigma);Dn[ii]+=rate;Dp[ii]+=rate;}}}}
static void apply_tri(int m,const double*L,const double*D,const double*U,const double*x,double*y){for(int i=0;i<m;i++)y[i]=D[i]*x[i]+(i?L[i]*x[i-1]:0)+(i<m-1?U[i]*x[i+1]:0);}
static int solve_M(int m,double h,const double*L,const double*D,const double*U,const double*rhs,double*x){double*lo=malloc(m*sizeof(double)),*di=malloc(m*sizeof(double)),*up=malloc(m*sizeof(double)),*rr=malloc(m*sizeof(double));for(int i=0;i<m;i++){lo[i]=-h*L[i];di[i]=1-h*D[i];up[i]=-h*U[i];rr[i]=rhs[i];}int ok=tridiag(m,lo,di,up,rr,x);free(lo);free(di);free(up);free(rr);return ok;}

typedef struct{int ord;double q,gamma,res,ms;int poisson,trisolves;} TCR;
static TCR transient_tc_nrii(const Device*d,double h,double mask,double theta,const double*N0,const double*P0,double*uout,double*Nout,double*Pout){int m=d->m;size_t sz=(MAXP+1)*(size_t)m;double*UC=calloc(sz,sizeof(double)),*NC=calloc(sz,sizeof(double)),*PC=calloc(sz,sizeof(double)),*Gn=malloc(m*sizeof(double)),*Gp=malloc(m*sizeof(double)),*Ln=calloc(m,sizeof(double)),*Dn=calloc(m,sizeof(double)),*Un=calloc(m,sizeof(double)),*Lp=calloc(m,sizeof(double)),*Dp=calloc(m,sizeof(double)),*Up=calloc(m,sizeof(double)),*Ax=malloc(m*sizeof(double)),*rhs=malloc(m*sizeof(double)),*next=malloc(m*sizeof(double));for(int i=0;i<m;i++){NC[i]=N0[i];PC[i]=P0[i];}poisson_coeff(d,NC,PC,UC,0);int psol=1,ts=0;build_A(d,mask,theta,UC,N0,P0,Ln,Dn,Un,Lp,Dp,Up);for(int i=0;i<m;i++){Nout[i]=N0[i];Pout[i]=P0[i];uout[i]=UC[i];}double prev=0,rat[8]={0},peak=0;int nr=0,ord=0;double t0=now_sec();for(int k=0;k<MAXP;k++){for(int ii=0;ii<m;ii++){int i=ii+1;double jrn,jrp,jln,jlp;edge_coeff_tc(d,k,i,i+1,UC,NC,PC,&jrn,&jrp);edge_coeff_tc(d,k,i-1,i,UC,NC,PC,&jln,&jlp);double Ns[MAXP+1]={0},Ps[MAXP+1]={0},Ss[MAXP+1]={0};for(int q=0;q<=k;q++){Ns[q]=NC[(size_t)q*m+ii];Ps[q]=PC[(size_t)q*m+ii];}s_srh(d,Ns,Ps,Ss,k);Gn[ii]=jrn-jln-Ss[k];Gp[ii]=-(jrp-jlp)-Ss[k];}
 int n=k+1;if(k==0){for(int i=0;i<m;i++)rhs[i]=h*Gn[i];}else{apply_tri(m,Ln,Dn,Un,NC+(size_t)k*m,Ax);for(int i=0;i<m;i++)rhs[i]=h*(Gn[i]-Ax[i]);}if(!solve_M(m,h,Ln,Dn,Un,rhs,next))break;ts++;memcpy(NC+(size_t)n*m,next,m*sizeof(double));if(k==0){for(int i=0;i<m;i++)rhs[i]=h*Gp[i];}else{apply_tri(m,Lp,Dp,Up,PC+(size_t)k*m,Ax);for(int i=0;i<m;i++)rhs[i]=h*(Gp[i]-Ax[i]);}if(!solve_M(m,h,Lp,Dp,Up,rhs,next))break;ts++;memcpy(PC+(size_t)n*m,next,m*sizeof(double));poisson_coeff(d,NC+(size_t)n*m,PC+(size_t)n*m,UC+(size_t)n*m,n);psol++;
 double mt=0,my=0;for(int i=0;i<m;i++){double tn=NC[(size_t)n*m+i],tp=PC[(size_t)n*m+i],tu=UC[(size_t)n*m+i];Nout[i]+=tn;Pout[i]+=tp;uout[i]+=tu;double aa=fmax(fabs(tn),fmax(fabs(tp),fabs(tu)));if(aa>mt)mt=aa;if(aa>peak)peak=aa;double yy=fmax(fabs(Nout[i]),fmax(fabs(Pout[i]),fabs(uout[i])));if(yy>my)my=yy;}ord=n;if(prev>0){rat[nr%8]=mt/prev;nr++;}prev=mt;if(mt<1e-11*(1+my))break;if(!isfinite(mt))break;}
 TCR z={0};z.ord=ord;int mm=nr<8?nr:8;if(mm){double tmp[8];for(int j=0;j<mm;j++)tmp[j]=rat[(nr-mm+j)%8];for(int a=0;a<mm;a++)for(int b=a+1;b<mm;b++)if(tmp[b]<tmp[a]){double t=tmp[a];tmp[a]=tmp[b];tmp[b]=t;}z.q=tmp[mm/2];}else z.q=NAN;double base=1;for(int i=0;i<m;i++){double v=fmax(fabs(N0[i]),fmax(fabs(P0[i]),fabs(UC[i])));if(v>base)base=v;}z.gamma=peak/base;z.ms=(now_sec()-t0)*1e3;z.poisson=psol;z.trisolves=ts;double*a=malloc(m*sizeof(double)),*b=malloc(m*sizeof(double)),*r=malloc(3*m*sizeof(double));for(int i=0;i<m;i++){a[i]=log(fmax(Nout[i],1e-300));b[i]=log(fmax(Pout[i],1e-300));}z.res=transient_residual(d,h,N0,P0,uout,a,b,r);free(a);free(b);free(r);free(UC);free(NC);free(PC);free(Gn);free(Gp);free(Ln);free(Dn);free(Un);free(Lp);free(Dp);free(Up);free(Ax);free(rhs);free(next);return z;}

int main(int argc,char**argv){int nn=argc>1?atoi(argv[1]):121;double theta=argc>2?atof(argv[2]):1.0,mask=2e-6;Device d;if(!device_init(&d,nn))return 2;int m=d.m;double*u=malloc(m*sizeof(double)),*a=malloc(m*sizeof(double)),*b=malloc(m*sizeof(double));device_set_bias(&d,0);DCSolve eq=equilibrium_pb(&d,u,a,b);if(eq.res>1e-8)return 3;for(int st=1;st<=20;st++){device_set_bias(&d,-5*st);double du=-5/d.Vt;for(int k=0;k<m;k++){double t=(double)(k+1)/(d.nn-1);u[k]+=(1-t)*du;}DCSolve z=dc_newton(&d,u,a,b,50,1e-12);if(z.res>1e-7)return 4;}double*N0=malloc(m*sizeof(double)),*P0=malloc(m*sizeof(double));for(int k=0;k<m;k++){N0[k]=exp(a[k]);P0[k]=exp(b[k]);}device_set_bias(&d,-101);double dts[]={1e-15,2e-15,5e-15,1e-14,2e-14,5e-14,1e-13,2e-13,5e-13,1e-12,2e-12,5e-12,1e-11};int nd=13;char path[256];snprintf(path,sizeof(path),"/mnt/data/nrii_si_pin_tc_resolvent_n%d_t%.2f.csv",nn,theta);FILE*f=fopen(path,"w");fprintf(f,"nodes,theta,dt_s,h,newton_ms,newton_it,newton_res,tc_ms,tc_order,tc_q,tc_gamma,tc_res,speedup,rel_diff,poisson_closures,tridiag_solves\n");for(int j=0;j<nd;j++){double dt=dts[j],h=dt/d.tau0;double*un=malloc(m*sizeof(double)),*an=malloc(m*sizeof(double)),*bn=malloc(m*sizeof(double)),*ur=malloc(m*sizeof(double)),*Nr=malloc(m*sizeof(double)),*Pr=malloc(m*sizeof(double));poisson_solve_np(&d,N0,P0,un);for(int k=0;k<m;k++){an[k]=log(N0[k]);bn[k]=log(P0[k]);}TRN tn=transient_newton(&d,h,N0,P0,un,an,bn);TCR rr=transient_tc_nrii(&d,h,mask,theta,N0,P0,ur,Nr,Pr);double md=0,mx=0;for(int k=0;k<m;k++){double z=fmax(fabs(exp(an[k])-Nr[k]),fmax(fabs(exp(bn[k])-Pr[k]),fabs(un[k]-ur[k])));if(z>md)md=z;double s=fmax(fabs(exp(an[k])),fmax(fabs(exp(bn[k])),fabs(un[k])));if(s>mx)mx=s;}double diff=md/(1+mx);fprintf(f,"%d,%.6g,%.12g,%.12g,%.9g,%d,%.3e,%.9g,%d,%.9g,%.9g,%.3e,%.9g,%.3e,%d,%d\n",nn,theta,dt,h,tn.ms,tn.it,tn.res,rr.ms,rr.ord,rr.q,rr.gamma,rr.res,tn.ms/rr.ms,diff,rr.poisson,rr.trisolves);fflush(f);fprintf(stderr,"n%d th%.2f dt%.1e q%.3g ord%d res%.1e diff%.1e sp%.3f\n",nn,theta,dt,rr.q,rr.ord,rr.res,diff,tn.ms/rr.ms);free(un);free(an);free(bn);free(ur);free(Nr);free(Pr);}fclose(f);return 0;}
